        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 0.9rem 1.2rem;
        border: 1px solid var(--line);
        border-radius: 999px;
        background: rgba(255, 255, 255, 0.72);
        backdrop-filter: blur(18px);
        box-shadow: 0 12px 30px rgba(16, 32, 51, 0.08);
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.75rem;
        font-weight: 700;
        text-decoration: none;
      }

      .brand-mark {
        display: grid;
        place-items: center;
        width: 2.5rem;
        height: 2.5rem;
        border-radius: 0.85rem;
        background: linear-gradient(135deg, var(--accent), #89a8ff);
        color: #fff;
        font-size: 1.15rem;
      }

      .hero {
        display: grid;
        grid-template-columns: 1.2fr 0.8fr;
        gap: 1.5rem;
        align-items: stretch;
        padding: 2rem 0 3rem;
      }

      .hero-copy,
      .hero-card,
      .faq-panel {
        border: 1px solid var(--line);
        background: var(--panel);
        backdrop-filter: blur(18px);
        box-shadow: var(--shadow);
      }

      .hero-copy {
        padding: clamp(1.5rem, 2vw, 2.5rem);
        border-radius: var(--radius-xl);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0.45rem 0.75rem;
        border-radius: 999px;
        background: rgba(79, 124, 255, 0.1);
        color: var(--accent-strong);
        font-size: 0.9rem;
        font-weight: 700;
        letter-spacing: 0.02em;
      }

      h1,
      h2,
      h3,
      p {
        margin-top: 0;
      }

      h1 {
        margin: 1rem 0;
        font-size: clamp(2.4rem, 5vw, 4.75rem);
        line-height: 1.05;
        letter-spacing: -0.04em;
      }

      .lede {
        max-width: 40rem;
        font-size: 1.05rem;
        color: var(--muted);
      }

      .hero-metrics {
        display: flex;
        flex-wrap: wrap;
        gap: 0.85rem;
        margin-top: 1.5rem;
      }

      .hero-metrics span {
        padding: 0.75rem 1rem;
        border: 1px solid rgba(79, 124, 255, 0.14);
        border-radius: 999px;
        background: var(--panel-strong);
        font-weight: 600;
      }

      .hero-card {
        display: grid;
        align-content: space-between;
        gap: 1.25rem;
        padding: 1.5rem;
        border-radius: var(--radius-xl);
      }

      .hero-card-art {
        min-height: 16rem;
        border-radius: var(--radius-lg);
        background:
          radial-gradient(circle at 35% 35%, rgba(255, 255, 255, 0.9), transparent 18%),
          radial-gradient(circle at 70% 30%, rgba(255, 255, 255, 0.85), transparent 14%),
          linear-gradient(145deg, #1d2841 0%, #355ee8 55%, #7c96ff 100%);
        position: relative;
        overflow: hidden;
      }

      .hero-card-art::before,
      .hero-card-art::after {
        content: "";
        position: absolute;
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.16);
      }

      .hero-card-art::before {
        width: 12rem;
        height: 12rem;
        inset: auto auto -3rem -3rem;
      }

      .hero-card-art::after {
        width: 9rem;
        height: 9rem;
        inset: 1.5rem -2rem auto auto;
      }

      .hero-card p {
        color: var(--muted);
      }

      main {
        padding-bottom: 4rem;
      }

      .faq-panel {
        padding: clamp(1.25rem, 2vw, 2rem);
        border-radius: var(--radius-xl);
      }

      .section-heading {
        display: flex;
        flex-wrap: wrap;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        margin-bottom: 1.25rem;
      }

      .section-heading p {
        max-width: 40rem;
        color: var(--muted);
        margin-bottom: 0;
      }

      .faq-list {
        display: grid;
        gap: 1rem;
      }

      .example {
        border: 1px solid var(--line);
        border-radius: var(--radius-lg);
        background: var(--panel-strong);
        overflow: hidden;
      }

      details {
        width: 100%;
      }

      summary {
        list-style: none;
      }

      summary::-webkit-details-marker {
        display: none;
      }

      .faq-trigger {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        width: 100%;
        padding: 1.2rem 1.25rem;
        cursor: pointer;
      }

      .faq-trigger h3 {
        margin-bottom: 0;
        font-size: 1.02rem;
      }

      .chevron {
        flex: none;
        width: 2.25rem;
        height: 2.25rem;
        border-radius: 999px;
        display: grid;
        place-items: center;
        background: rgba(79, 124, 255, 0.12);
        color: var(--accent-strong);
        transition: transform 0.2s ease, background-color 0.2s ease;
      }

      details[open] .chevron {
        transform: rotate(180deg);
        background: rgba(79, 124, 255, 0.18);
      }

      .details {
        padding: 0 1.25rem 1.25rem;
        color: var(--muted);
      }

      .details p:last-child {
        margin-bottom: 0;
      }

      summary:hover .chevron {
        background: rgba(79, 124, 255, 0.18);
      }

      .faq-trigger:focus-visible,
      .top-bar a:focus-visible,
      .skip-link:focus-visible {
        outline: 3px solid var(--accent);
        outline-offset: 4px;
      }

      footer {
        padding: 0 0 2.5rem;
      }

      .footer-card {
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        padding: 1rem 1.25rem;
        border: 1px solid var(--line);
        border-radius: 1.25rem;
        color: var(--muted);
        background: rgba(255, 255, 255, 0.65);
      }

      @media (max-width: 800px) {
        .hero {
          grid-template-columns: 1fr;
        }

        .top-bar,
        .footer-card,
        .section-heading {
          align-items: flex-start;
        }
      }

      @media (max-width: 560px) {
        .page-shell {
          width: min(calc(100% - 1rem), var(--max-width));
        }

        .top-bar,
        .hero-copy,
        .hero-card,
        .faq-panel,
        .footer-card {
          padding-left: 1rem;
          padding-right: 1rem;
        }

        .faq-trigger {
          padding: 1rem;
        }

        .details {
          padding: 0 1rem 1rem;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        html {
          scroll-behavior: auto;
        }

