        *::before,
        *::after {
          transition: none !important;
          animation: none !important;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --panel: Canvas;
          --panel-strong: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --line: ButtonBorder;
          --accent: Highlight;
          --accent-strong: Highlight;
          --shadow: none;
        }

        .brand-mark,
        .chevron,
        .eyebrow,
        .hero-metrics span {
          border: 1px solid ButtonBorder;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <div id="app"></div>

    <script>
      const faqItems = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats often purr when they feel calm and safe, but purring can also help them self-soothe when they are stressed or recovering. It is one of the ways cats communicate comfort, attention, and physical regulation."
        },
        {
          question: "How much sleep do cats usually need?",
          answer:
            "Most adult cats sleep between 12 and 16 hours a day, while kittens and older cats may sleep even more. Their sleep pattern comes from their natural predator instincts: short bursts of energy followed by long rest periods."
        },
        {
          question: "Why do cats knead blankets and laps?",
          answer:
            "Kneading is a behavior that starts in kittenhood, when kittens press against their mother to encourage milk flow. Many adult cats keep doing it because it feels soothing, familiar, and safe."
        },
        {
          question: "What is the safest way to introduce a new cat at home?",
          answer:
            "Start slowly with separate spaces, separate resources, and short scent exchanges before face-to-face meetings. Gradual introductions reduce stress and give each cat time to build confidence."
        },
        {
          question: "Why do cats stare out the window for so long?",
          answer:
            "Windows act like live entertainment for cats. Birds, people, leaves, and changing light give them visual stimulation, which supports curiosity and helps indoor cats stay mentally engaged."
        },
        {
          question: "Do indoor cats still need enrichment?",
          answer:
            "Yes. Indoor cats benefit from scratching posts, climbing areas, puzzle feeders, play sessions, and quiet hiding spots. Enrichment helps prevent boredom and supports healthy movement and behavior."
        }
      ];

      const escapeHtml = (value) =>
        value
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");

      const Header = () => `
        <header class="page-shell">
          <div class="top-bar">
            <a class="brand" href="#maincontent">
              <span class="brand-mark" aria-hidden="true">🐾</span>
              <span>Cat FAQ</span>
            </a>
            <span aria-label="Frequently asked questions about cats">Practical answers for curious cat people</span>
          </div>
        </header>
      `;

      const Hero = () => `
        <section class="hero page-shell" aria-labelledby="hero-title">
          <div class="hero-copy">
            <span class="eyebrow">Cat care essentials</span>
            <h1 id="hero-title">A polished FAQ page for common cat questions.</h1>
            <p class="lede">
              Explore quick, friendly answers about cat behavior, routines, and home life. Each question starts collapsed so visitors can open only what they need.
            </p>
            <div class="hero-metrics" aria-label="Highlights">
              <span>6 clear answers</span>
              <span>Collapsed by default</span>
              <span>Keyboard friendly</span>
            </div>
          </div>
          <aside class="hero-card" aria-label="Page highlight">
            <div class="hero-card-art" aria-hidden="true"></div>
            <div>
              <h2>Built like a product page</h2>
              <p>
                Clean spacing, soft glassmorphism surfaces, and simple disclosure interactions keep the experience modern without getting in the way of the content.
              </p>
            </div>
          </aside>
        </section>
      `;

      const FAQItem = ({ question, answer }) => `
        <div class="example">
          <details>
            <summary class="faq-trigger">
              <h3>${escapeHtml(question)}</h3>
              <span class="chevron" aria-hidden="true">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                  <path d="M6 9l6 6 6-6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path>
                </svg>
              </span>
            </summary>
            <div class="details">
              <p>${escapeHtml(answer)}</p>
            </div>
          </details>
        </div>
      `;

      const FAQSection = () => `
        <section class="page-shell faq-panel" aria-labelledby="faq-heading">
          <div class="section-heading">
            <div>
              <h2 id="faq-heading">Frequently asked questions</h2>
              <p>Questions are collapsed by default and can be expanded individually.</p>
            </div>
          </div>
          <div class="faq-list">
            ${faqItems.map((item) => FAQItem(item)).join("")}
          </div>
        </section>
      `;

      const Footer = () => `
        <footer class="page-shell">
          <div class="footer-card">
            <span>Cat FAQ demo</span>
            <span>Designed as a single standalone HTML document</span>
          </div>
        </footer>
      `;

      const App = () => `
        ${Header()}
        <main id="maincontent" tabindex="-1">
          ${Hero()}
          ${FAQSection()}
        </main>
        ${Footer()}
      `;

      document.getElementById("app").innerHTML = App();
    </script>
  </body>
</html>
